-- Milestone 1 ("nothing fake, nothing broken") — additive only.
-- 1) Checkout now collects a phone number and rider instructions.
-- 2) Every restaurant gets a full menu (6-8 dishes). Photos live in public/images
--    (freely licensed, credited in public/images/CREDITS.md and on /credits).
-- Safe to re-run: columns use IF NOT EXISTS, dishes use ON CONFLICT DO NOTHING.
-- Existing orders, users and dishes are not modified.

alter table public.orders add column if not exists customer_phone text;
alter table public.orders add column if not exists address_notes text;

on conflict (id) do nothing;
